// 正月初一的儒略历标签（儒略历史实口径）与结构字段。
struct DatongYear {
  int year;          // 农历年号（= 正月初一所在儒略历年）
  const char* iso;   // 正月初一，儒略历 yyyy-mm-dd
  int monthCount;    // 月数（12 或 13）
  int leapAfter;     // 0 = 无闰月；n = 第 n 月之后插闰 n 月
  unsigned lenMask;  // bit i = 时间序第 i 月 30 天
};

